// ===========================================================================
// Embedded module registry: CommonJS-style loader for the transpiled source closure and the override modules.
// Module ids are paths relative to src/ WITH the .ts extension. The only bare specifier allowed is node:crypto.
// ===========================================================================
const __srcModules = {};
function __srcDefine(id, fn) { if (__srcModules[id]) throw new Error('duplicate embedded module ' + id); __srcModules[id] = { fn, exports: null }; }
function __srcResolve(fromId, spec) {
  if (spec === 'node:crypto' || spec === 'crypto') return null;
  if (!spec.startsWith('.')) throw new Error(`embedded module ${fromId} requires a bare specifier ${spec} (only node:crypto is allowed)`);
  const dir = fromId.split('/').slice(0, -1);
  for (const seg of spec.split('/')) { if (seg === '.') continue; else if (seg === '..') dir.pop(); else dir.push(seg); }
  return dir.join('/') + '.ts';
}
function __srcRequire(spec, fromId = '') {
  const id = fromId ? __srcResolve(fromId, spec) : spec;
  if (id === null) return __nodeCrypto;
  const m = __srcModules[id];
  if (!m) throw new Error('embedded module not found: ' + id + ' (from ' + (fromId || '<root>') + ')');
  if (m.exports === null) {
    m.exports = {};
    const mod = { exports: m.exports };
    m.fn(m.exports, mod, (s) => __srcRequire(s, id));
    m.exports = mod.exports;
  }
  return m.exports;
}

